import React from 'react';
import ReactMarkdown from 'react-markdown';
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize';
import remarkGfm from 'remark-gfm';

// Strict schema restricting protocol schemes to https
const secureSchema = {
  ...defaultSchema,
  protocols: {
    ...defaultSchema.protocols,
    href: ['https', 'http', 'mailto'],
    src: ['https']
  }
};

export function SafeAiMarkdownViewer({ content }: { content: string }) {
  return (
    <div className="prose prose-invert max-w-none">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[[rehypeSanitize, secureSchema]]}
        components={{
          // Enforce external link security attributes
          a: ({ node, ...props }) => (
            <a {...props} target="_blank" rel="noopener noreferrer" className="text-accent-fg underline" />
          )
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
}

using System.Net;

public class SsrfSafeHttpClient
{
    public static async Task<string> FetchPublicUrlAsync(string targetUrl, CancellationToken ct = default)
    {
        var uri = new Uri(targetUrl);
        if (uri.Scheme != Uri.UriSchemeHttps)
            throw new SecurityException("Only HTTPS URLs are permitted.");

        // Resolve IP addresses and block private/loopback ranges
        var hostAddresses = await Dns.GetHostAddressesAsync(uri.DnsSafeHost, ct);
        foreach (var ip in hostAddresses)
        {
            if (IPAddress.IsLoopback(ip) || IsPrivateSubnet(ip) || ip.ToString() == "169.254.169.254")
            {
                throw new SecurityException($"Access to private or metadata network address '{ip}' is blocked.");
            }
        }

        using var httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
        return await httpClient.GetStringAsync(uri, ct);
    }

    private static bool IsPrivateSubnet(IPAddress ip)
    {
        var bytes = ip.GetAddressBytes();
        return (bytes[0] == 10) ||                               // 10.0.0.0/8
               (bytes[0] == 172 && bytes[1] >= 16 && bytes[1] <= 31) || // 172.16.0.0/12
               (bytes[0] == 192 && bytes[1] == 168);             // 192.168.0.0/16
    }
}
